/// Which earbud a [`gauge`] represents.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Side {
    Left,
    Right,
}

/// Built once: a handle hashes its whole document on creation, and `view`
/// runs every frame.
static EARBUD_LEFT: LazyLock<svg::Handle> =
    LazyLock::new(|| svg::Handle::from_memory(EARBUD_SVG_LEFT.as_bytes()));
static EARBUD_RIGHT: LazyLock<svg::Handle> =
    LazyLock::new(|| svg::Handle::from_memory(EARBUD_SVG_RIGHT.as_bytes()));

fn earbud_image<'a>(side: Side) -> Element<'a, Message> {
    let handle = match side {
        Side::Left => EARBUD_LEFT.clone(),
        Side::Right => EARBUD_RIGHT.clone(),
    };

    container(
        svg(handle)
            .width(Length::Fixed(44.0))
            .height(Length::Fixed(56.0)),
    )
    .width(Length::Fill)
    .align_x(Alignment::Center)
    .into()
}

/// An earbud tile for the Home tab.
pub fn gauge<'a>(side: Side, label: String, level: Option<f32>) -> Element<'a, Message> {
    let value_text = match level {
        Some(pct) => format!("{:.0}%", pct * 100.0),
        None => "—".to_string(),
    };

    let fill_pct = (level.unwrap_or(0.0).clamp(0.0, 1.0) * 100.0).round() as u16;
    let empty_pct = 100u16.saturating_sub(fill_pct);
    let has_level = level.is_some();

    let fill = container(text(""))
        .width(Length::FillPortion(fill_pct.max(1)))
        .height(Length::Fill)
        .style(move |theme: &Theme| {
            let ext = theme.extended_palette();
            let color = if has_level {
                ext.success.strong.color
            } else {
                iced::Color::TRANSPARENT
            };
            container::Style {
                background: Some(color.into()),
                border: iced::Border {
                    radius: 5.0.into(),
                    ..Default::default()
                },
                ..Default::default()
            }
        });

    let empty = container(text("")).width(Length::FillPortion(empty_pct.max(1)));

    let track = container(row![fill, empty].height(Length::Fill))
        .width(Length::Fill)
        .height(10)
        .padding(2)
        .style(|theme: &Theme| {
            let ext = theme.extended_palette();
            container::Style {
                background: Some(ext.background.base.color.into()),
                border: iced::Border {
                    color: ext.background.strong.color,
                    width: 1.0,
                    radius: 6.0.into(),
                },
                ..Default::default()
            }
        });

    column![
        earbud_image(side),
        text(label).size(11).style(text::secondary),
        track,
        text(value_text).size(15),
    ]
    .spacing(8)
    .align_x(Alignment::Center)
    .width(Length::Fill)
    .into()
}
